const SENIOR_ENGLISH: MCQ[] = [
  { id: 'ss-e-1', q: 'A "bildungsroman" is a story about:', choices: ['A detective', 'Coming of age', 'A war', 'A romance only'], answer: 1, explanation: 'Bildungsroman traces moral and psychological growth from youth to adulthood.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-2', q: 'Aristotle’s three rhetorical appeals are:', choices: ['Logos, pathos, ethos', 'Story, plot, theme', 'Hero, villain, helper', 'Past, present, future'], answer: 0, explanation: 'Logos (logic), pathos (emotion), ethos (credibility) underpin classical rhetoric.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-3', q: '"The Great Gatsby" was written by:', choices: ['Hemingway', 'F. Scott Fitzgerald', 'Faulkner', 'Steinbeck'], answer: 1, explanation: 'Fitzgerald’s 1925 novel is a Senior English staple.', acCode: 'AC9E10LE01', unit: 1 },
  { id: 'ss-e-4', q: '"Synecdoche" is when:', choices: ['Two opposites combine', 'A part represents the whole (or vice versa)', 'Two ideas contrast', 'A word imitates a sound'], answer: 1, explanation: '"All hands on deck" — hands stands for sailors.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-5', q: '"Stream of consciousness" is most associated with:', choices: ['Hemingway', 'James Joyce', 'Tolkien', 'Twain'], answer: 1, explanation: 'Joyce’s "Ulysses" (1922) is a defining modernist example.', acCode: 'AC9E10LE03' },
  { id: 'ss-e-6', q: 'The "unreliable narrator" technique means:', choices: ['The plot is wrong', 'The narrator’s account may be distorted', 'No narrator is present', 'The story is non-fiction'], answer: 1, explanation: 'Readers must read against the grain of the narration — e.g. in "Lolita" or "Gone Girl".', acCode: 'AC9E10LE02' },
  { id: 'ss-e-7', q: 'A "denouement" is the:', choices: ['Opening conflict', 'Climax', 'Resolution', 'Setting'], answer: 2, explanation: 'Denouement (French for "untying") resolves the narrative’s tensions.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-8', q: '"Beware the ides of March" appears in:', choices: ['Hamlet', 'Macbeth', 'Julius Caesar', 'Othello'], answer: 2, explanation: 'The Soothsayer’s warning to Caesar in Shakespeare’s "Julius Caesar".', acCode: 'AC9E10LE01' },
  { id: 'ss-e-9', q: 'Modernist literature largely emerged in the:', choices: ['1700s', '1800s', 'Early 1900s', '1980s'], answer: 2, explanation: 'Modernism rose after WWI — Eliot’s "The Waste Land" (1922), Woolf, Joyce.', acCode: 'AC9E10LE03', unit: 2 },
  { id: 'ss-e-10', q: '"Ad hominem" is a logical fallacy that:', choices: ['Cites tradition', 'Attacks the person, not the argument', 'Uses circular reasoning', 'Presents a false dichotomy'], answer: 1, explanation: 'Ad hominem dodges the argument by going after the speaker’s character.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-11', q: 'The "tragic flaw" of a hero is also called:', choices: ['Hubris', 'Hamartia', 'Catharsis', 'Pathos'], answer: 1, explanation: 'Hamartia is Aristotle’s term; hubris (excessive pride) is one common form.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-12', q: 'A "thesis statement" should be:', choices: ['A question', 'A specific arguable claim', 'A summary of the topic', 'A neutral fact'], answer: 1, explanation: 'A thesis takes a debatable position the essay then defends with evidence.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-13', q: 'Postmodern texts often feature:', choices: ['Linear plots', 'Metafiction and intertextuality', 'Reliable narrators only', 'Single perspectives'], answer: 1, explanation: 'Postmodern fiction self-references and plays with other texts (e.g. Calvino, Atwood).', acCode: 'AC9E10LE03', unit: 3 },
  { id: 'ss-e-14', q: '"Iambic pentameter" describes a line of:', choices: ['Five iambs (ten syllables) of unstressed-stressed', 'Six trochees', 'Three anapests', 'Four spondees'], answer: 0, explanation: 'Shakespearean blank verse runs in iambic pentameter — da-DUM × 5.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-15', q: '"To Kill a Mockingbird" examines:', choices: ['Climate change', 'Racism in 1930s American South', 'Renaissance art', 'WWII Russia'], answer: 1, explanation: 'Lee’s novel uses Scout’s perspective to explore prejudice and conscience.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-16', q: '"Catharsis" in tragedy refers to:', choices: ['Comic relief', 'Emotional release in the audience', 'A plot twist', 'A change of setting'], answer: 1, explanation: 'Aristotle described tragedy as purging pity and fear in the audience.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-17', q: '"Allegory" is:', choices: ['A direct comparison', 'A narrative with a deeper symbolic meaning', 'A one-line joke', 'A type of metaphor'], answer: 1, explanation: 'Animal Farm is an allegory of the Russian Revolution.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-18', q: 'Margaret Atwood’s "The Handmaid’s Tale" is a:', choices: ['Romance', 'Dystopian novel', 'Memoir', 'Historical biography'], answer: 1, explanation: 'Atwood’s 1985 novel explores theocratic dystopia and women’s rights.', acCode: 'AC9E10LE01', unit: 2 },
  { id: 'ss-e-19', q: 'A "syllogism" is:', choices: ['A type of poem', 'A deductive argument with two premises and a conclusion', 'A rhetorical question', 'A fallacy'], answer: 1, explanation: 'All humans are mortal; Socrates is human; therefore Socrates is mortal.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-20', q: 'Modernist poet T.S. Eliot wrote:', choices: ['"The Waste Land"', '"Paradise Lost"', '"Beowulf"', '"The Canterbury Tales"'], answer: 0, explanation: 'Eliot’s 1922 fragmentary poem is a key modernist text.', acCode: 'AC9E10LE01' },
  { id: 'ss-e-21', q: '"Foreshadowing" is when a text:', choices: ['Concludes the story', 'Hints at events to come', 'Repeats earlier scenes', 'Lists characters'], answer: 1, explanation: 'Foreshadowing builds anticipation by planting clues.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-22', q: '"Pastiche" means:', choices: ['Original work in a fresh genre', 'Imitating the style of other writers or texts', 'A short poem', 'A literary award'], answer: 1, explanation: 'Pastiche borrows another’s manner, often respectfully — common in postmodern writing.', acCode: 'AC9E10LE03' },
  { id: 'ss-e-23', q: 'A "didactic" text aims to:', choices: ['Entertain only', 'Teach a moral or instruct', 'Confuse the reader', 'Stay neutral'], answer: 1, explanation: 'Didactic works (fables, religious parables) carry an explicit lesson.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-24', q: 'A "soliloquy" is:', choices: ['A duet between characters', 'A character speaking thoughts aloud, alone on stage', 'A stage direction', 'A chorus line'], answer: 1, explanation: 'Hamlet’s "To be or not to be" is the most famous soliloquy in English.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-25', q: 'A "feminist reading" of a text might focus on:', choices: ['Plant imagery', 'How gender, power and women’s experience are represented', 'Sentence length', 'Rhyme scheme'], answer: 1, explanation: 'Feminist criticism examines representation, voice and ideology relating to gender.', acCode: 'AC9E10LE05', unit: 3 },
];

const SENIOR_MATHS: MCQ[] = [
  { id: 'ss-m-1', q: 'Derivative of x³:', choices: ['x²', '3x²', '3x', 'x³/3'], answer: 1, explanation: 'd/dx(x^n) = n·x^(n−1).', unit: 3 },
  { id: 'ss-m-2', q: 'sin(90°) = ?', choices: ['0', '0.5', '1', '√2/2'], answer: 2, explanation: 'At 90°, the sine reaches its maximum of 1.' },
  { id: 'ss-m-3', q: 'Quadratic formula solves ax² + bx + c = 0; x = ?', choices: ['(−b ± √(b²−4ac)) / 2a', '−b / a', 'b² − 4ac', 'c / (a + b)'], answer: 0, explanation: 'Works for any quadratic; the discriminant b²−4ac tells you the nature of the roots.', acCode: 'AC9M10A05' },
  { id: 'ss-m-4', q: 'log₁₀(1000) = ?', choices: ['1', '2', '3', '10'], answer: 2, explanation: '10³ = 1000, so log base 10 of 1000 is 3.', unit: 2 },
  { id: 'ss-m-5', q: 'Integral of 2x dx:', choices: ['x² + C', '2 + C', 'x + C', 'x²/2 + C'], answer: 0, explanation: 'Power rule for integration: ∫2x dx = x² + C.', unit: 3 },
  { id: 'ss-m-6', q: 'Probability of two independent events both occurring:', choices: ['P(A) + P(B)', 'P(A) × P(B)', 'P(A) − P(B)', 'P(A)/P(B)'], answer: 1, explanation: 'Multiplication rule for independent events.', acCode: 'AC9M10P01', unit: 1 },
  { id: 'ss-m-7', q: 'cos²(θ) + sin²(θ) = ?', choices: ['0', 'θ', '1', '2'], answer: 2, explanation: 'Pythagorean trig identity — fundamental.', unit: 1 },
  { id: 'ss-m-8', q: 'For y = e^x, dy/dx = ?', choices: ['x', '1', 'e^x', 'ln(x)'], answer: 2, explanation: 'The natural exponential is its own derivative.', unit: 3 },
  { id: 'ss-m-9', q: 'Number of permutations of 5 distinct items:', choices: ['25', '120', '60', '720'], answer: 1, explanation: '5! = 5 × 4 × 3 × 2 × 1 = 120.', unit: 2 },
  { id: 'ss-m-10', q: 'Standard deviation measures:', choices: ['The mean', 'The spread of data', 'The mode', 'The maximum'], answer: 1, explanation: 'σ quantifies how far values typically deviate from the mean.', acCode: 'AC9M10ST02' },
  { id: 'ss-m-11', q: 'A vector in 3D has how many components?', choices: ['1', '2', '3', '4'], answer: 2, explanation: 'A 3D vector has x, y and z components.', unit: 1 },
  { id: 'ss-m-12', q: 'The complex number i is defined by:', choices: ['i = 1', 'i = −1', 'i² = −1', 'i² = 1'], answer: 2, explanation: 'i² = −1 is the foundation of complex numbers (Specialist Maths).', unit: 1 },
  { id: 'ss-m-13', q: 'In a normal distribution, ~68% of data lies within:', choices: ['1 SD of the mean', '2 SD of the mean', '3 SD of the mean', 'The mean exactly'], answer: 0, explanation: 'The 68–95–99.7 rule for normal distributions.', acCode: 'AC9M10ST02', unit: 4 },
  { id: 'ss-m-14', q: 'The compound interest formula is:', choices: ['A = P(1 + rt)', 'A = P(1 + r/n)^(nt)', 'A = Pe^(rt) only', 'A = P − rt'], answer: 1, explanation: 'Compound interest grows by powers of the period rate; simple interest is linear (A = P(1+rt)).', acCode: 'AC9M10N01', unit: 2 },
  { id: 'ss-m-15', q: 'tan(45°) = ?', choices: ['0', '1/2', '1', '√3'], answer: 2, explanation: 'At 45°, sine and cosine are equal, so tan = 1.' },
  { id: 'ss-m-16', q: 'A function f(x) = 1/x is undefined at:', choices: ['x = 1', 'x = 0', 'x = −1', 'x = ∞'], answer: 1, explanation: 'Division by zero is undefined — there’s a vertical asymptote at x = 0.', unit: 1 },
  { id: 'ss-m-17', q: 'For data 4, 6, 6, 7, 12, the median is:', choices: ['6', '7', '8', '12'], answer: 0, explanation: 'Middle value of an ordered list of five numbers is the third one — 6.', acCode: 'AC9M10ST01' },
  { id: 'ss-m-18', q: '∫ 1/x dx =', choices: ['x + C', 'ln|x| + C', '1/(x²) + C', 'e^x + C'], answer: 1, explanation: 'A standard integral every Methods student memorises.', unit: 3 },
  { id: 'ss-m-19', q: 'In a binomial distribution, "n choose k" counts the:', choices: ['Number of trials', 'Probability of success', 'Number of ways to pick k from n', 'Mean'], answer: 2, explanation: 'Combinations: C(n, k) = n! / (k!(n−k)!).', unit: 2 },
  { id: 'ss-m-20', q: 'A "stationary point" of f(x) is where:', choices: ['f(x) = 0', "f'(x) = 0", "f''(x) = 0", 'f(x) is undefined'], answer: 1, explanation: 'Derivative is zero — could be a maximum, minimum or point of inflection.', unit: 3 },
  { id: 'ss-m-21', q: '"Pearson’s r" measures:', choices: ['Probability of an event', 'Strength of linear correlation', 'Median', 'Mode'], answer: 1, explanation: 'r ranges from −1 to 1; near ±1 means a strong linear relationship.', acCode: 'AC9M10ST02', unit: 4 },
  { id: 'ss-m-22', q: 'The geometric mean of 4 and 9:', choices: ['5', '6', '6.5', '13'], answer: 1, explanation: '√(4 × 9) = √36 = 6.', acCode: 'AC9M10ST01' },
  { id: 'ss-m-23', q: 'Solve for x: 2^x = 32', choices: ['3', '4', '5', '6'], answer: 2, explanation: '2^5 = 32. (Equivalent to log₂(32) = 5.)', acCode: 'AC9M10A04' },
  { id: 'ss-m-24', q: 'Cross product of vectors a × b is:', choices: ['A scalar', 'A vector perpendicular to both a and b', 'Always zero', 'The dot product'], answer: 1, explanation: 'Cross product is a 3D operation producing a perpendicular vector — Specialist Maths.', unit: 3 },
  { id: 'ss-m-25', q: 'In hypothesis testing, "p < 0.05" usually means:', choices: ['Result is certain', 'Null hypothesis is rejected at 5% significance', 'Sample is too small', 'Test failed'], answer: 1, explanation: 'A p-value below 0.05 is conventionally treated as statistically significant evidence against the null.', unit: 4 },
];

const SENIOR_HISTORY: MCQ[] = [
  { id: 'ss-h-1', q: 'The Russian Revolution occurred in:', choices: ['1905', '1917', '1929', '1945'], answer: 1, explanation: 'The February and October revolutions of 1917 ended Tsarist rule and brought the Bolsheviks to power.', acCode: 'AC9HH10K02' },
  { id: 'ss-h-2', q: 'The Treaty of Versailles ended:', choices: ['World War I', 'World War II', 'The Cold War', 'The Vietnam War'], answer: 0, explanation: 'Signed in 1919, it imposed harsh reparations on Germany and reshaped Europe.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-3', q: 'The Cold War was primarily between:', choices: ['USA & UK', 'USSR & China', 'USA & USSR', 'France & Germany'], answer: 2, explanation: 'A geopolitical and ideological stand-off lasting roughly 1947–1991.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-4', q: 'The Berlin Wall fell in:', choices: ['1969', '1979', '1989', '1999'], answer: 2, explanation: 'On 9 November 1989 — symbolically ending the Cold War in Europe.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-5', q: 'Apartheid in South Africa officially ended in:', choices: ['1976', '1985', '1991', '2001'], answer: 2, explanation: 'Legal apartheid was dismantled in 1991; Mandela was elected president in 1994.', acCode: 'AC9HH10K04', unit: 2 },
  { id: 'ss-h-6', q: 'The 1967 Australian referendum recognised:', choices: ['Decimal currency', 'Aboriginal people in the census', 'Capital change', 'New national anthem'], answer: 1, explanation: '90%+ said yes to counting First Nations peoples and allowing federal laws for them.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-7', q: 'The Mabo decision (1992) overturned the doctrine of:', choices: ['Terra nullius', 'Eminent domain', 'Habeas corpus', 'Res judicata'], answer: 0, explanation: 'Terra nullius — "land belonging to no one" — was the legal fiction underlying British claims.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-8', q: 'The Universal Declaration of Human Rights was adopted in:', choices: ['1918', '1945', '1948', '1968'], answer: 2, explanation: 'The UN General Assembly adopted the UDHR in December 1948.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-9', q: 'Australian combat troops withdrew from Vietnam in:', choices: ['1965', '1972', '1975', '1980'], answer: 1, explanation: 'Whitlam ended Australian combat involvement in 1972.', acCode: 'AC9HH10K02', unit: 1 },
  { id: 'ss-h-10', q: 'Decolonisation in Africa peaked during the:', choices: ['1920s', '1940s', '1960s', '1980s'], answer: 2, explanation: 'Most African nations gained independence in the 1960s.', acCode: 'AC9HH10K03', unit: 2 },
  { id: 'ss-h-11', q: 'The Holocaust killed approximately:', choices: ['600,000 Jews', '6 million Jews', '60 million Jews', '600 million Jews'], answer: 1, explanation: 'Nazi Germany systematically murdered approximately 6 million European Jews.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-12', q: 'The Cuban Missile Crisis happened in:', choices: ['1956', '1962', '1968', '1975'], answer: 1, explanation: 'October 1962 — the closest the world came to nuclear war.', acCode: 'AC9HH10K03', unit: 3 },
  { id: 'ss-h-13', q: 'Pearl Harbor was attacked on:', choices: ['7 December 1941', '6 June 1944', '11 November 1918', '1 September 1939'], answer: 0, explanation: 'Japan’s surprise attack brought the USA into WWII.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-14', q: 'The Nuremberg Trials prosecuted:', choices: ['Soviet defectors', 'Nazi war criminals', 'Japanese emperors', 'British generals'], answer: 1, explanation: 'Held 1945–46 — established the principle of crimes against humanity.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-15', q: 'The Vietnam War involved Australia from:', choices: ['1962 to 1972', '1939 to 1945', '1950 to 1953', '1979 to 1989'], answer: 0, explanation: 'Australia first sent advisors in 1962 and withdrew combat troops by 1972.', acCode: 'AC9HH10K02' },
  { id: 'ss-h-16', q: 'The 1948 Israeli War followed:', choices: ['Yalta Conference', 'UN Partition Plan for Palestine', 'Versailles Treaty', 'Sykes-Picot Agreement'], answer: 1, explanation: 'The UN’s 1947 partition plan led directly to the 1948 Arab–Israeli War.', acCode: 'AC9HH10K03', unit: 4 },
  { id: 'ss-h-17', q: 'The "Iron Curtain" speech was given by:', choices: ['Roosevelt', 'Churchill', 'Stalin', 'Truman'], answer: 1, explanation: 'Churchill’s 1946 Fulton speech named the Cold War divide.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-18', q: 'The Vietnam Tet Offensive was in:', choices: ['1965', '1968', '1973', '1975'], answer: 1, explanation: 'The 1968 offensive shifted American public opinion against the war.', acCode: 'AC9HH10K02', unit: 3 },
  { id: 'ss-h-19', q: 'The Whitlam government was dismissed in:', choices: ['1972', '1975', '1983', '1991'], answer: 1, explanation: 'Governor-General Sir John Kerr dismissed PM Whitlam on 11 November 1975 — Australia’s constitutional crisis.', acCode: 'AC9HH10K04', unit: 4 },
  { id: 'ss-h-20', q: 'The League of Nations was replaced by the:', choices: ['Warsaw Pact', 'United Nations', 'NATO', 'European Union'], answer: 1, explanation: 'The UN was founded in 1945 after the League failed to prevent WWII.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-21', q: 'The Apology to the Stolen Generations was delivered in:', choices: ['2000', '2005', '2008', '2013'], answer: 2, explanation: 'PM Kevin Rudd apologised in Parliament on 13 February 2008.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-22', q: 'Mao Zedong proclaimed the People’s Republic of China in:', choices: ['1945', '1949', '1956', '1976'], answer: 1, explanation: 'After defeating the Nationalists, Mao founded the PRC on 1 October 1949.', acCode: 'AC9HH10K03', unit: 3 },
  { id: 'ss-h-23', q: 'The Nuremberg Laws (1935) targeted:', choices: ['Trade unions', 'Jewish citizens of Germany', 'Communists', 'Catholic clergy'], answer: 1, explanation: 'Nazi race laws stripped Jewish Germans of citizenship and forbade certain marriages.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-24', q: 'The Civil Rights Act in the USA passed in:', choices: ['1954', '1964', '1972', '1980'], answer: 1, explanation: 'The 1964 Civil Rights Act outlawed segregation and discrimination in the USA.', acCode: 'AC9HH10K03', unit: 2 },
  { id: 'ss-h-25', q: 'The Sydney Olympics were held in:', choices: ['1996', '2000', '2004', '2008'], answer: 1, explanation: 'Sydney hosted the Games of the new millennium in September 2000.', acCode: 'AC9HH10K04' },
];

const SENIOR_GEOGRAPHY: MCQ[] = [
  { id: 'ss-g-1', q: 'The carbon cycle moves carbon between:', choices: ['Only the atmosphere and oceans', 'Atmosphere, biosphere, hydrosphere and geosphere', 'Only the biosphere', 'Only the hydrosphere'], answer: 1, explanation: 'Carbon cycles between all four major Earth systems through processes like photosynthesis and combustion.', acCode: 'AC9HG10K02', unit: 1 },
  { id: 'ss-g-2', q: 'Demographic transition theory describes changes in:', choices: ['Climate', 'Birth and death rates', 'Plate tectonics', 'Currency'], answer: 1, explanation: 'A 5-stage model linking economic development to falling birth and death rates.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-3', q: 'A "megacity" has a population over:', choices: ['1 million', '5 million', '10 million', '50 million'], answer: 2, explanation: 'UN definition: an urban agglomeration of over 10 million people.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-4', q: 'Eutrophication is mainly caused by:', choices: ['Drought', 'Nutrient runoff (esp. nitrogen and phosphorus)', 'Earthquakes', 'Salt water'], answer: 1, explanation: 'Excess nutrients feed algal blooms, depleting oxygen and killing aquatic life.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-5', q: 'OPEC mainly produces:', choices: ['Coffee', 'Oil', 'Grain', 'Steel'], answer: 1, explanation: 'OPEC = Organization of Petroleum Exporting Countries.', unit: 3 },
  { id: 'ss-g-6', q: 'The 2015 Paris Agreement targets keeping warming below:', choices: ['1°C', '1.5°C', '3°C', '5°C'], answer: 1, explanation: 'Aim to limit global warming to well below 2°C and ideally to 1.5°C above pre-industrial levels.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-7', q: 'ENSO refers to:', choices: ['El Niño – Southern Oscillation', 'European North Sea Org.', 'Equatorial Northern Sky Object', 'East-North Stratospheric Outflow'], answer: 0, explanation: 'ENSO drives major climate variability across the Pacific.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-8', q: 'Which is a "developed" economy by World Bank classification?', choices: ['India', 'Indonesia', 'Australia', 'Vietnam'], answer: 2, explanation: 'Australia is a high-income economy by World Bank measures.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-9', q: 'Coral bleaching is mainly driven by:', choices: ['Boat traffic', 'Ocean warming', 'Tides', 'Salinity drops'], answer: 1, explanation: 'Heat stress expels symbiotic algae from coral, leaving white skeletons.', acCode: 'AC9HG10K03' },
  { id: 'ss-g-10', q: 'A "primary industry" is one that:', choices: ['Manufactures goods', 'Extracts raw materials', 'Provides services', 'Builds software'], answer: 1, explanation: 'Primary = extraction (farming, fishing, mining). Secondary = manufacturing. Tertiary = services.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-11', q: 'A "sustainable yield" of a forest means:', choices: ['Harvesting more than grows back', 'Harvesting at or below the rate of regrowth', 'No harvesting at all', 'Burning the forest'], answer: 1, explanation: 'Sustainable yields preserve the resource for future generations.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-12', q: 'The "urban heat island" effect describes:', choices: ['Hot springs in cities', 'Cities being warmer than surrounding countryside', 'Volcanic activity near urban areas', 'Heatwaves only in summer'], answer: 1, explanation: 'Concrete, asphalt and reduced vegetation make cities significantly warmer than nearby rural land.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-13', q: 'Australia’s largest export to China by value (recent years) has been:', choices: ['Wine', 'Iron ore', 'Wheat', 'Education'], answer: 1, explanation: 'Iron ore dominates Australia–China trade flows.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-14', q: 'A "tipping point" in climate science refers to:', choices: ['A gradual change', 'A threshold beyond which large, often irreversible change occurs', 'A small fluctuation', 'A periodic cycle'], answer: 1, explanation: 'Examples: collapse of the West Antarctic ice sheet or amazon dieback.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-15', q: 'GIS stands for:', choices: ['Global Internet System', 'Geographic Information System', 'Geological Index Scale', 'Government Indexed Standards'], answer: 1, explanation: 'GIS lets geographers layer and analyse spatial data.', acCode: 'AC9HG10S02' },
  { id: 'ss-g-16', q: 'A "youthful" age-sex pyramid suggests:', choices: ['Ageing population', 'High birth rates and low life expectancy', 'Stable population', 'Zero growth'], answer: 1, explanation: 'Wide-based pyramids show many young people — common in less-developed countries.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-17', q: 'Sea level rise is mainly caused by:', choices: ['Tides', 'Thermal expansion + ice-sheet melt', 'River runoff', 'Rainfall'], answer: 1, explanation: 'Water expands as it warms; melting land ice adds new water to the oceans.', acCode: 'AC9HG10K03' },
  { id: 'ss-g-18', q: 'A "biocapacity" measurement compares:', choices: ['Carbon emissions to GDP', 'Biological resources available vs ecological demand', 'Birth rates to death rates', 'Trade to debt'], answer: 1, explanation: 'Used to assess whether a country is living within its ecological means.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-19', q: 'Which country is the largest CO₂ emitter today?', choices: ['USA', 'Russia', 'China', 'India'], answer: 2, explanation: 'China became the largest annual emitter around 2006 (though per-capita and historical emissions differ).', acCode: 'AC9HG10K03' },
  { id: 'ss-g-20', q: 'A "food desert" is:', choices: ['A type of biome', 'An area with limited access to fresh, affordable food', 'A region with frequent droughts', 'A protected wilderness'], answer: 1, explanation: 'Common in poorer urban neighbourhoods lacking supermarkets.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-21', q: 'Globalisation tends to increase:', choices: ['Trade barriers', 'Interconnection of economies and cultures', 'Self-sufficiency of nations', 'Use of local languages only'], answer: 1, explanation: 'Globalisation links markets, supply chains, media and migration patterns worldwide.', acCode: 'AC9HG10K01', unit: 3 },
  { id: 'ss-g-22', q: 'The "World Heritage" listing of Kakadu protects:', choices: ['Cultural and natural values', 'Only natural rock formations', 'Just Aboriginal art sites', 'Mining claims'], answer: 0, explanation: 'Kakadu is dual-listed for natural and cultural significance.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-23', q: 'The Three Gorges Dam in China was built primarily for:', choices: ['Tourism', 'Hydroelectric power and flood control', 'Salt extraction', 'Defence'], answer: 1, explanation: 'World’s largest hydropower station — also displaced over a million residents.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-24', q: 'The "Anthropocene" refers to:', choices: ['An ancient ice age', 'The current proposed epoch of significant human impact on Earth', 'A type of rock', 'A future star'], answer: 1, explanation: 'Some geologists propose this label for the era dominated by human-driven planetary change.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-25', q: 'A "Gini coefficient" close to 0 indicates:', choices: ['Perfect inequality', 'Perfect equality', 'High poverty', 'Strong economic growth'], answer: 1, explanation: 'The Gini ranges 0 (perfect equality) to 1 (perfect inequality).', acCode: 'AC9HG10K01', unit: 2 },
];

const SENIOR_SCIENCE: MCQ[] = [
  { id: 'ss-s-1', q: 'Mitochondria are best known as the:', choices: ['Powerhouse of the cell', 'Storage for water', 'Information centre', 'Waste disposal'], answer: 0, explanation: 'They generate ATP through cellular respiration.', acCode: 'AC9S10U01', unit: 1 },
  { id: 'ss-s-2', q: 'The atomic number of an element equals its number of:', choices: ['Neutrons', 'Protons', 'Electrons in outer shell', 'Energy levels'], answer: 1, explanation: 'Atomic number = protons (and electrons in a neutral atom).', acCode: 'AC9S10U02' },
  { id: 'ss-s-3', q: 'Newton’s Second Law: F = ?', choices: ['m × v', 'm × a', 'a × v', 'm + a'], answer: 1, explanation: 'Force equals mass times acceleration.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-4', q: 'A "covalent bond" forms when atoms:', choices: ['Transfer electrons', 'Share electrons', 'Repel each other', 'Donate protons'], answer: 1, explanation: 'Ionic bonds transfer; covalent bonds share. Water (H₂O) is covalent.', acCode: 'AC9S10U02', unit: 1 },
  { id: 'ss-s-3b', q: 'DNA replication is described as:', choices: ['Conservative', 'Semi-conservative', 'Dispersive', 'Repetitive'], answer: 1, explanation: 'Each new DNA molecule keeps one parent strand and one new strand.', acCode: 'AC9S10U01', unit: 1 },
  { id: 'ss-s-5', q: 'The pH of pure water is:', choices: ['1', '7', '10', '14'], answer: 1, explanation: 'Pure water is neutral — pH 7.', acCode: 'AC9S10U02' },
  { id: 'ss-s-6', q: 'The kinetic energy of an object is given by:', choices: ['mgh', '½mv²', 'mv', 'm/v'], answer: 1, explanation: 'KE = ½mv²; mgh is gravitational potential energy.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-7', q: 'Photosynthesis takes place in the:', choices: ['Nucleus', 'Mitochondrion', 'Chloroplast', 'Ribosome'], answer: 2, explanation: 'Chloroplasts contain chlorophyll, which captures light energy.', acCode: 'AC9S10U01' },
  { id: 'ss-s-8', q: 'The Doppler effect explains:', choices: ['The colour of fire', 'Shift in wave frequency due to relative motion', 'How magnets attract', 'How fission works'], answer: 1, explanation: 'A passing siren’s pitch drops as it moves away from you.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-9', q: 'Hubble’s Law links a galaxy’s:', choices: ['Mass and brightness', 'Distance and recession velocity', 'Spin and shape', 'Age and chemistry'], answer: 1, explanation: 'Galaxies further away recede faster — evidence for an expanding universe.', acCode: 'AC9S10U04', unit: 4 },
  { id: 'ss-s-10', q: 'A "catalyst" in a reaction:', choices: ['Is consumed', 'Speeds the reaction without being consumed', 'Stops the reaction', 'Makes products toxic'], answer: 1, explanation: 'Catalysts lower activation energy and are regenerated at the reaction’s end.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-11', q: 'Natural selection requires:', choices: ['No variation', 'Variation, heritability, differential survival', 'Equal reproduction', 'Identical organisms'], answer: 1, explanation: 'Darwin’s mechanism: heritable variation + selective pressure → adaptation over generations.', acCode: 'AC9S10U01' },
  { id: 'ss-s-12', q: 'A "redox" reaction involves:', choices: ['Only acid–base exchange', 'Transfer of electrons between species', 'Phase changes', 'Distillation'], answer: 1, explanation: 'Reduction = gain of electrons; oxidation = loss. They always occur together.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-13', q: 'The "Standard Model" of particle physics includes:', choices: ['Only protons', 'Quarks, leptons and force-carrier bosons', 'Just atoms', 'Only neutrinos'], answer: 1, explanation: 'Six quarks, six leptons (incl. electron, neutrinos) and bosons (incl. the Higgs).', acCode: 'AC9S10U02', unit: 4 },
  { id: 'ss-s-14', q: 'Genetically, a male in humans has chromosomes:', choices: ['XX', 'XY', 'YY', 'XXY only'], answer: 1, explanation: 'In humans, XY usually develops as male; XX as female.', acCode: 'AC9S10U01' },
  { id: 'ss-s-15', q: 'Conservation of energy means energy can:', choices: ['Be destroyed', 'Be created from nothing', 'Only change form, never be created or destroyed', 'Disappear in friction'], answer: 2, explanation: 'First law of thermodynamics — energy is conserved, even when transformed.', acCode: 'AC9S10U02' },
  { id: 'ss-s-16', q: 'Ohm’s Law states:', choices: ['V = IR', 'P = V²/I', 'V = I + R', 'R = V × I'], answer: 0, explanation: 'Voltage = current × resistance for a linear (ohmic) conductor.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-17', q: 'The "greenhouse effect" is caused by:', choices: ['Volcanic dust only', 'Gases absorbing infrared radiation', 'The ozone hole', 'Solar flares'], answer: 1, explanation: 'CO₂, methane, water vapour and others trap outgoing infrared, warming the planet.', acCode: 'AC9S10U03' },
  { id: 'ss-s-18', q: 'The "specific heat capacity" of water is:', choices: ['Low compared to other liquids', 'Very high compared to most substances', 'Negative', 'Always zero'], answer: 1, explanation: 'Water resists temperature change — important for climate moderation and biology.', acCode: 'AC9S10U02' },
  { id: 'ss-s-19', q: 'Enzymes are made of:', choices: ['Carbohydrates', 'Lipids', 'Proteins', 'DNA'], answer: 2, explanation: 'Enzymes are protein biological catalysts (with rare RNA exceptions).', acCode: 'AC9S10U01' },
  { id: 'ss-s-20', q: 'A "blue shift" in stellar spectra implies the star is:', choices: ['Moving away from us', 'Moving toward us', 'Stationary', 'Cool'], answer: 1, explanation: 'Wavelengths compress when an object approaches — the relativistic Doppler effect.', acCode: 'AC9S10U04', unit: 4 },
  { id: 'ss-s-21', q: 'Mendel’s laws describe:', choices: ['Plate tectonics', 'Inheritance patterns of traits', 'Chemical bonding', 'Wave behaviour'], answer: 1, explanation: 'Gregor Mendel’s pea experiments founded modern genetics.', acCode: 'AC9S10U01' },
  { id: 'ss-s-22', q: 'A solution with pH 2 compared to pH 4 is:', choices: ['Slightly more acidic', '100× more acidic', '2× more acidic', 'Less acidic'], answer: 1, explanation: 'pH is logarithmic — each unit is a 10× change in [H+].', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-23', q: 'Plate tectonics theory was firmly established in the:', choices: ['1800s', '1940s', '1960s', '1990s'], answer: 2, explanation: 'Seafloor spreading evidence in the 1960s confirmed Wegener’s earlier ideas.', acCode: 'AC9S10U03' },
  { id: 'ss-s-24', q: 'The half-life of a radioactive isotope is:', choices: ['Time for all atoms to decay', 'Time for half the atoms to decay', 'Time to form an isotope', 'Time for the element to change colour'], answer: 1, explanation: 'Used in carbon dating and nuclear medicine.', acCode: 'AC9S10U02', unit: 4 },
  { id: 'ss-s-25', q: 'In stellar evolution, our Sun will eventually become a:', choices: ['Black hole', 'Neutron star', 'Red giant then white dwarf', 'Supernova'], answer: 2, explanation: 'Sun-mass stars run out of hydrogen, swell into red giants and end as cooling white dwarfs.', acCode: 'AC9S10U04', unit: 4 },
];

// ============================================================
//  SENIOR — COMPUTING  (VCE Software Development Units 3–4)
//  Anchored to VCAA Applied Computing Study Design 2025–2028.
//  All items tagged unit: 3 or 4. Use cases: Quick Quiz, Buzzer
//  Round, Question Generator. Mix of factual recall and concept
//  application across all four Areas of Study.
// ============================================================
const SENIOR_COMPUTING: MCQ[] = [
  // -- Unit 3 AOS 1: Programming (1–25) --
  { id: 'ss-comp-1', q: 'The four stages of the VCAA problem-solving methodology are:', choices: ['Plan, Code, Test, Ship', 'Analysis, Design, Development, Evaluation', 'Brief, Build, Beta, Bug-fix', 'Requirements, Mock-up, Module, Markup'], answer: 1, explanation: 'The methodology has four stages: Analysis → Design → Development → Evaluation.', unit: 3 },
  { id: 'ss-comp-2', q: 'Which OOP principle bundles data with the methods that operate on it and controls access via modifiers?', choices: ['Abstraction', 'Inheritance', 'Encapsulation', 'Generalisation'], answer: 2, explanation: 'Encapsulation hides internal state behind public/protected/private access controls.', unit: 3 },
  { id: 'ss-comp-3', q: 'Which OOP principle lets a subclass acquire members from a superclass?', choices: ['Abstraction', 'Inheritance', 'Encapsulation', 'Generalisation'], answer: 1, explanation: 'Inheritance: the child class gains attributes and methods from its parent.', unit: 3 },
  { id: 'ss-comp-4', q: 'Hiding internal complexity and exposing only essential features describes:', choices: ['Encapsulation', 'Abstraction', 'Inheritance', 'Iteration'], answer: 1, explanation: 'Abstraction reduces cognitive load by surfacing only what the user needs to know.', unit: 3 },
  { id: 'ss-comp-5', q: 'Generalisation in OOP design means:', choices: ['Writing vague comments', 'Identifying common features across classes and lifting them into a more general superclass', 'Naming variables generically', 'Skipping validation for general users'], answer: 1, explanation: 'Generalisation is the design counterpart to inheritance — factoring shared behaviour upward.', unit: 3 },
  { id: 'ss-comp-6', q: 'Which data type best stores the value 42 with no decimal part?', choices: ['Floating point', 'String', 'Integer', 'Boolean'], answer: 2, explanation: 'Integers store whole numbers; floats store decimals; booleans store true/false.', unit: 3 },
  { id: 'ss-comp-7', q: 'Which data type stores only the values true or false?', choices: ['Integer', 'Boolean', 'Character', 'Date/time'], answer: 1, explanation: 'Boolean has exactly two possible values: true or false.', unit: 3 },
  { id: 'ss-comp-8', q: 'A variable holding the value 3.14159 is best declared as:', choices: ['Integer', 'Floating point', 'String', 'Boolean'], answer: 1, explanation: 'Floating-point types store numbers with a fractional component.', unit: 3 },
  { id: 'ss-comp-9', q: 'A one-dimensional array is best described as:', choices: ['A collection of records of different data types', 'A linear list of elements of the same data type', 'A grid of rows and columns', 'A tree of nodes'], answer: 1, explanation: '1D arrays are ordered, fixed-type sequences indexed from 0 (or 1, depending on language).', unit: 3 },
  { id: 'ss-comp-10', q: 'Which data structure best stores a chessboard?', choices: ['One-dimensional array', 'Two-dimensional array', 'Boolean variable', 'Single record'], answer: 1, explanation: 'A 2D array maps naturally to rows × columns — like an 8×8 chessboard.', unit: 3 },
  { id: 'ss-comp-11', q: 'A record (struct) differs from an array because it:', choices: ['Can only hold numbers', 'Holds multiple fields of possibly different data types', 'Is always one-dimensional', 'Cannot be passed to functions'], answer: 1, explanation: 'Records group heterogeneous fields under one name, accessed by field index/name.', unit: 3 },
  { id: 'ss-comp-12', q: 'Which file format is comma-delimited and commonly used to exchange tabular data?', choices: ['TXT', 'CSV', 'XML', 'JPG'], answer: 1, explanation: 'CSV (Comma-Separated Values) stores tabular data — one row per line, fields separated by commas.', unit: 3 },
  { id: 'ss-comp-13', q: 'XML files structure data using:', choices: ['Commas', 'Fixed-width columns', 'Nested tags with opening and closing brackets', 'Pipe characters'], answer: 2, explanation: 'XML uses hierarchical tags (e.g. <student><name>...</name></student>).', unit: 3 },
  { id: 'ss-comp-14', q: 'The naming convention strFirstName is an example of:', choices: ['snake_case', 'camelCase', 'Hungarian notation', 'PascalCase'], answer: 2, explanation: 'Hungarian notation prefixes the variable with its data type (str = string).', unit: 3 },
  { id: 'ss-comp-15', q: 'The variable name studentScore follows the convention:', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'Kebab-case'], answer: 0, explanation: 'camelCase: lowercase first word, then capitalise each subsequent word, no separators.', unit: 3 },
  { id: 'ss-comp-16', q: 'The variable name total_marks is written in:', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'PascalCase'], answer: 1, explanation: 'snake_case uses lowercase letters joined by underscores.', unit: 3 },
  { id: 'ss-comp-17', q: 'An existence check on user input verifies that:', choices: ['The value is the correct data type', 'The value falls within a specified range', 'A required field has been entered and is not blank', 'The value is unique in the database'], answer: 2, explanation: 'Existence (presence) checking confirms a mandatory field is not empty.', unit: 3 },
  { id: 'ss-comp-18', q: 'A type check confirms that data entered:', choices: ['Falls within a permitted minimum and maximum', 'Is of the expected data type (e.g. integer)', 'Matches a value in another table', 'Is not blank'], answer: 1, explanation: 'Type checking rejects, for example, alphabetic input where an integer was expected.', unit: 3 },
  { id: 'ss-comp-19', q: 'Range checking on a student-age field ensures the value:', choices: ['Is exactly 18', 'Falls between a defined minimum and maximum', 'Is unique', 'Matches the data type'], answer: 1, explanation: 'Range checks reject values outside an allowed interval (e.g. ages 5–99).', unit: 3 },
  { id: 'ss-comp-20', q: 'Selection sort has an average-case time complexity of:', choices: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], answer: 3, explanation: 'Selection sort scans the remaining list each pass — O(n²) comparisons.', unit: 3 },
  { id: 'ss-comp-21', q: 'Quick sort has an average-case time complexity of:', choices: ['O(n²)', 'O(n log n)', 'O(n)', 'O(1)'], answer: 1, explanation: 'Quick sort averages O(n log n); worst case is O(n²) when pivots are poor.', unit: 3 },
  { id: 'ss-comp-22', q: 'Binary search requires the data to be:', choices: ['Unique', 'Numerical only', 'Sorted', 'Stored in an XML file'], answer: 2, explanation: 'Binary search halves a sorted list each step — it cannot operate on unsorted data.', unit: 3 },
  { id: 'ss-comp-23', q: 'Linear search works by:', choices: ['Halving the list at each step', 'Checking every element in turn from start to end', 'Hashing the target', 'Sorting first, then searching'], answer: 1, explanation: 'Linear search is O(n) but works on any list — sorted or unsorted.', unit: 3 },
  { id: 'ss-comp-24', q: 'A missing semicolon that prevents the program from running is which type of error?', choices: ['Logic error', 'Runtime error', 'Syntax error', 'Validation error'], answer: 2, explanation: 'Syntax errors violate language rules and are caught before execution.', unit: 3 },
  { id: 'ss-comp-25', q: 'A program that compiles and runs but produces the wrong answer has a:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Type error'], answer: 1, explanation: 'Logic errors give incorrect output even though the syntax is valid.', unit: 3 },
  // -- Unit 3 AOS 2: Analysis & Design (26–50) --
  { id: 'ss-comp-26', q: 'Dividing by zero at execution time produces a:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Compile-time error'], answer: 2, explanation: 'Runtime errors arise during execution — divide-by-zero, index out of range, type mismatch, overflow.', unit: 3 },
  { id: 'ss-comp-27', q: 'A breakpoint in a debugger:', choices: ['Stops the program permanently', 'Pauses execution at a chosen line so variables can be inspected', 'Deletes the next instruction', 'Optimises performance'], answer: 1, explanation: 'Breakpoints let developers inspect program state mid-run without rebuilding.', unit: 3 },
  { id: 'ss-comp-28', q: 'A testing table typically compares:', choices: ['Variables and constants', 'Expected output with actual output for given test data', 'Functional and non-functional requirements', 'Public and private members'], answer: 1, explanation: 'Test cases pair input + expected vs actual output to confirm a module behaves as intended.', unit: 3 },
  { id: 'ss-comp-29', q: 'Internal documentation in code primarily exists to:', choices: ['Replace external user manuals', 'Explain data and code structures and aid future maintenance', 'Increase the file size', 'Bypass type checking'], answer: 1, explanation: 'Comments and docstrings help future developers (and your future self) understand intent.', unit: 3 },
  { id: 'ss-comp-30', q: 'An emerging trend in programming with AI is:', choices: ['Removing all variables', 'Using natural-language prompts to generate code', 'Banning testing', 'Forbidding internal documentation'], answer: 1, explanation: 'AI code generators turn prompts into source — but require responsible, ethical use.', unit: 3 },
  { id: 'ss-comp-31', q: 'A FOR loop is an example of which control structure?', choices: ['Sequence', 'Selection', 'Iteration (repetition)', 'Encapsulation'], answer: 2, explanation: 'FOR, WHILE and REPEAT…UNTIL all express iteration/repetition.', unit: 3 },
  { id: 'ss-comp-32', q: 'An IF…ELSE statement is an example of which control structure?', choices: ['Sequence', 'Selection (branching)', 'Iteration', 'Recursion'], answer: 1, explanation: 'Selection chooses between code paths based on a condition.', unit: 3 },
  { id: 'ss-comp-33', q: 'A "brief" in a Software Development project documents:', choices: ['The marketing strategy', 'The problem/need/opportunity, proposed users and chosen programming language', 'The completed source code', 'The marking rubric'], answer: 1, explanation: 'A brief is a short scoping document submitted early in the SAT.', unit: 3 },
  { id: 'ss-comp-34', q: 'A Gantt chart is primarily used to:', choices: ['Diagram class inheritance', 'Visualise task sequencing, dependencies and time allocation', 'Model data flow', 'Document encryption keys'], answer: 1, explanation: 'Gantt charts plot tasks on a timeline showing dependencies and milestones.', unit: 3 },
  { id: 'ss-comp-35', q: 'The critical path on a Gantt chart is:', choices: ['The longest path of dependent tasks that determines minimum project duration', 'The shortest task', 'The hidden tasks', 'The lunch break'], answer: 0, explanation: 'Critical-path tasks have no slack — slipping them delays the whole project.', unit: 3 },
  { id: 'ss-comp-36', q: 'A milestone in project management is:', choices: ['A single line of code', 'A significant point or event marking progress', 'A type of bug', 'A subclass'], answer: 1, explanation: 'Milestones mark notable checkpoints (e.g. "design folio complete").', unit: 3 },
  { id: 'ss-comp-37', q: 'A non-functional requirement describes:', choices: ['What the system does', 'A quality attribute such as usability, reliability or maintainability', 'Hardware costs', 'Source code style'], answer: 1, explanation: 'Functional = what it does; non-functional = how well it does it.', unit: 3 },
  { id: 'ss-comp-38', q: 'A functional requirement of a login system would be:', choices: ['The login screen should load within 2 seconds', 'The system shall authenticate users via username and password', 'The system should be intuitive', 'The system should be available 99% of the time'], answer: 1, explanation: 'Functional requirements specify behaviours; the others are performance/usability/availability — non-functional.', unit: 3 },
  { id: 'ss-comp-39', q: 'Economic, legal, social and technical are categories of:', choices: ['Data types', 'Constraints', 'OOP principles', 'Test cases'], answer: 1, explanation: 'Solution constraints fall into these four broad categories per the study design.', unit: 3 },
  { id: 'ss-comp-40', q: 'The solution scope describes:', choices: ['The marketing budget', 'The boundaries — what will and will not be addressed', 'The IDE settings', 'The colour palette'], answer: 1, explanation: 'Scope establishes the limits/boundaries of the solution.', unit: 3 },
  { id: 'ss-comp-41', q: 'A context diagram (Level 0) typically shows:', choices: ['Every internal process', 'The system as a single process plus external entities and data flows', 'Class inheritance', 'Sorting algorithms'], answer: 1, explanation: 'Level 0 = a one-bubble overview; Level 1 DFD then decomposes the bubble.', unit: 3 },
  { id: 'ss-comp-42', q: 'A data flow diagram (Level 1) decomposes a system into:', choices: ['Processes, entities, data stores and data flows', 'Classes and objects', 'Test cases and assertions', 'Roles and permissions only'], answer: 0, explanation: 'Level 1 DFDs expand the system into internal processes and data stores.', unit: 3 },
  { id: 'ss-comp-43', q: 'In a use case diagram, an "actor" is:', choices: ['A class within the system', 'An external entity (user or system) that interacts with the system', 'The system database', 'A test case'], answer: 1, explanation: 'Actors sit outside the system boundary and trigger or receive use cases.', unit: 3 },
  { id: 'ss-comp-44', q: 'In UML use case diagrams the «includes» relationship means:', choices: ['Optional behaviour', 'Mandatory sub-behaviour shared by multiple use cases', 'Class inheritance', 'A delete action'], answer: 1, explanation: '«includes» is mandatory; «extends» is optional/conditional.', unit: 3 },
  { id: 'ss-comp-45', q: 'A Software Requirements Specification (SRS) typically defines:', choices: ['Marketing collateral', 'Functional and non-functional requirements, constraints, scope, user characteristics and technical environment', 'The Gantt chart only', 'Only the user interface'], answer: 1, explanation: 'The SRS is the central analysis artefact for the SAT.', unit: 3 },
  { id: 'ss-comp-46', q: 'Which is a method for collecting primary data?', choices: ['A published government report', 'A survey conducted by the developer', 'A textbook chapter', 'Wikipedia'], answer: 1, explanation: 'Primary data is collected by the researcher; the others are secondary sources.', unit: 3 },
  { id: 'ss-comp-47', q: 'A differential backup contains:', choices: ['A full copy of all data', 'Changes since the last full backup', 'Changes since the last backup of any kind', 'Encrypted hashes only'], answer: 1, explanation: 'Differential = since last full; incremental = since last backup of any kind.', unit: 3 },
  { id: 'ss-comp-48', q: 'An incremental backup contains:', choices: ['A full copy of all data', 'Changes since the last full backup', 'Changes since the last backup of any kind', 'Only the operating system'], answer: 2, explanation: 'Incrementals are smaller and faster than differentials but slower to restore.', unit: 3 },
  { id: 'ss-comp-49', q: 'Version control software exists primarily to:', choices: ['Encrypt source code', 'Track changes to files over time and enable branching/merging', 'Optimise execution speed', 'Generate documentation'], answer: 1, explanation: 'Git, Subversion and similar tools preserve history and coordinate teamwork.', unit: 3 },
  { id: 'ss-comp-50', q: 'A mood board is a/an:', choices: ['Design tool for detailed pseudocode', 'Ideation tool for collecting visual references and inspiration', 'Testing strategy', 'Bug-tracking system'], answer: 1, explanation: 'Mood boards live in the ideation phase of design, capturing tone and aesthetic.', unit: 3 },
  // -- Unit 4 AOS 1: Development & Evaluation (51–75) --
  { id: 'ss-comp-51', q: 'A data dictionary documents:', choices: ['Programmer jokes', 'Each data element — name, type, size, validation and description', 'Just the table names', 'Only the foreign keys'], answer: 1, explanation: 'Data dictionaries give a single source of truth for every field in the design.', unit: 4 },
  { id: 'ss-comp-52', q: 'An IPO chart describes:', choices: ['Inputs, Processes and Outputs of a module', 'Internal Procedure Order', 'Independent Programming Object', 'Iteration, Persistence, Output'], answer: 0, explanation: 'IPO = Input → Process → Output — a classic design tool for module behaviour.', unit: 4 },
  { id: 'ss-comp-53', q: 'Pseudocode is best described as:', choices: ['Compiled machine code', 'English-like statements expressing an algorithm independent of any programming language', 'A debugging tool', 'A version control system'], answer: 1, explanation: 'Pseudocode communicates logic without language-specific syntax.', unit: 4 },
  { id: 'ss-comp-54', q: 'Affordance in user experience (UX) refers to:', choices: ['The cost of the software', 'Visual or behavioural cues that suggest how an element can be used', 'How much memory the app uses', 'The number of users'], answer: 1, explanation: 'A button that looks pressable "affords" pressing — a key UX cue.', unit: 4 },
  { id: 'ss-comp-55', q: 'The design principle of "contrast" mainly helps with:', choices: ['File compression', 'Drawing attention to important elements and improving readability', 'Loop unrolling', 'Encryption'], answer: 1, explanation: 'Contrast distinguishes elements visually, aiding hierarchy and accessibility.', unit: 4 },
  { id: 'ss-comp-56', q: 'The Copyright Act 1968 (Cwlth) primarily protects:', choices: ['Personal data', 'Original literary, artistic and software works', 'Trademarks', 'Patents'], answer: 1, explanation: 'Copyright covers original works — including source code as a literary work.', unit: 4 },
  { id: 'ss-comp-57', q: 'The Privacy Act 1988 is a:', choices: ['Victorian Act', 'Federal (Commonwealth) Act', 'School policy', 'Industry standard'], answer: 1, explanation: 'Privacy Act 1988 (Cwlth) is federal; the Vic equivalent is the Privacy and Data Protection Act 2014.', unit: 4 },
  { id: 'ss-comp-58', q: 'Australian Privacy Principle (APP) 11 covers:', choices: ['Direct marketing', 'Security of personal information', 'Access to personal information', 'Anonymity and pseudonymity'], answer: 1, explanation: 'APP 11 requires organisations to take reasonable steps to protect personal information they hold.', unit: 4 },
  { id: 'ss-comp-59', q: 'Efficient and effective solutions are characterised by:', choices: ['Maximum lines of code', 'User-centred design, clear and concise code, and detailed internal documentation', 'Encrypting every variable', 'Using global variables exclusively'], answer: 1, explanation: 'The study design lists these three characteristics explicitly for Unit 4 AOS 1.', unit: 4 },
  { id: 'ss-comp-60', q: 'Which access modifier restricts a class member to be visible only within its own class?', choices: ['public', 'protected', 'private', 'internal'], answer: 2, explanation: 'private = same class only. protected adds subclasses; public adds the whole world.', unit: 4 },
  { id: 'ss-comp-61', q: 'Which access modifier exposes a class member to subclasses but not to unrelated classes?', choices: ['public', 'protected', 'private', 'static'], answer: 1, explanation: 'protected = visible to the declaring class and any subclasses.', unit: 4 },
  { id: 'ss-comp-62', q: 'A code repository (e.g. Git on GitHub) primarily supports:', choices: ['Image rendering', 'Storing source code, tracking history and enabling collaboration', 'Database design', 'Sound synthesis'], answer: 1, explanation: 'Repos are the foundation of modern version control and team development.', unit: 4 },
  { id: 'ss-comp-63', q: 'An API is best described as:', choices: ['A type of database', 'A defined interface that lets one piece of software request services from another', 'A backup format', 'A user interface element'], answer: 1, explanation: 'APIs define endpoints and contracts; libraries package reusable functionality.', unit: 4 },
  { id: 'ss-comp-64', q: 'Alpha testing is performed by:', choices: ['End users in production', 'Developers and internal testers in a development environment', 'Random customers via app stores', 'Auditors only'], answer: 1, explanation: 'Alpha = internal. Beta = potential end users in a production-like environment.', unit: 4 },
  { id: 'ss-comp-65', q: 'Beta testing is performed by:', choices: ['Developers writing the code', 'Compilers', 'Potential end users in an environment similar to deployment', 'Automated bots only'], answer: 2, explanation: 'Beta puts the solution in front of real users to gather feedback before release.', unit: 4 },
  { id: 'ss-comp-66', q: 'A beta-testing plan should include:', choices: ['Marketing budget', 'Test scenarios, observation method and how results will be recorded', 'Server hardware specs only', 'The encryption algorithm'], answer: 1, explanation: 'Per study design: testing plan, test scenarios, observation, documentation of results.', unit: 4 },
  { id: 'ss-comp-67', q: 'An evaluation strategy specifies:', choices: ['Only the criteria', 'Criteria, time frame and responsibility', 'The Gantt chart colour scheme', 'The IDE shortcut keys'], answer: 1, explanation: 'Per study design: evaluation strategies cover criteria + time frame + responsibility.', unit: 4 },
  { id: 'ss-comp-68', q: '"Scope creep" refers to:', choices: ['A bug that copies data', 'Uncontrolled expansion of project requirements beyond the original scope', 'A search algorithm', 'A type of recursion'], answer: 1, explanation: 'Scope creep is a leading cause of project plan failure.', unit: 4 },
  { id: 'ss-comp-69', q: 'When assessing project plan effectiveness, you should review:', choices: ['Only the final code', 'The number of changes made, the reasons for them and their impact on completion', 'The colour palette only', 'The compiler version'], answer: 1, explanation: 'These three are the explicit assessment criteria in the study design.', unit: 4 },
  { id: 'ss-comp-70', q: 'Which is NOT a factor that influences project plan effectiveness per the study design?', choices: ['Scope creep', 'Personnel changes', 'Technical issues', 'Variable names'], answer: 3, explanation: 'The three factors listed are scope creep, personnel changes and technical issues.', unit: 4 },
  { id: 'ss-comp-71', q: 'A project journal/log is used to:', choices: ['Replace the IDE', 'Monitor and document progress, decisions and changes throughout the project', 'Store user passwords', 'Render graphics'], answer: 1, explanation: 'Journals support reflective practice and provide evidence of progress for the SAT.', unit: 4 },
  { id: 'ss-comp-72', q: '"Commenting out" code is a debugging technique that:', choices: ['Permanently deletes the lines', 'Temporarily disables lines so the program runs without them', 'Encrypts the lines', 'Sends the lines to a server'], answer: 1, explanation: 'Useful for isolating which block is causing a bug without losing the code.', unit: 4 },
  { id: 'ss-comp-73', q: 'Constructing relevant test data means:', choices: ['Using only random values', 'Designing inputs that exercise valid, invalid, boundary and edge cases', 'Always using the production database', 'Avoiding negative numbers'], answer: 1, explanation: 'Good test data includes typical, boundary and invalid inputs.', unit: 4 },
  { id: 'ss-comp-74', q: 'AI assistants in software development (e.g. Copilot) are best used:', choices: ['To replace all human code review', 'As a productivity aid, with outputs critically reviewed and tested by the developer', 'To bypass version control', 'To skip documentation'], answer: 1, explanation: 'Responsible use treats AI output as a draft, not a finished product.', unit: 4 },
  { id: 'ss-comp-75', q: 'An overflow error is a type of:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Validation error'], answer: 2, explanation: 'Overflow occurs when a calculation exceeds the maximum value the data type can hold — at runtime.', unit: 4 },
  // -- Unit 4 AOS 2: Secure software development practices (76–100) --
  { id: 'ss-comp-76', q: 'An advantage of developing software in-house rather than externally is:', choices: ['Guaranteed lower cost', 'Greater control over requirements, IP and security practices', 'No need for testing', 'No need for legal compliance'], answer: 1, explanation: 'In-house dev gives the organisation tighter control, though it can require more upfront resourcing.', unit: 4 },
  { id: 'ss-comp-77', q: 'A common vulnerability of an insecurely designed API is:', choices: ['It uses too much electricity', 'It exposes data or functions without sufficient authentication or rate-limiting', 'It is written in a high-level language', 'It contains comments'], answer: 1, explanation: 'Poorly secured APIs are a major attack surface — broken auth, excessive data exposure, etc.', unit: 4 },
  { id: 'ss-comp-78', q: 'Malware is software that:', choices: ['Improves performance', 'Is intentionally designed to damage, disrupt or gain unauthorised access', 'Is open-source', 'Is licensed under GPL'], answer: 1, explanation: 'Malware umbrella includes viruses, worms, ransomware, spyware, trojans.', unit: 4 },
  { id: 'ss-comp-79', q: 'Why is unpatched software a security risk?', choices: ['It looks ugly', 'Known vulnerabilities remain exploitable until the patch is applied', 'It runs slower', 'It uses more disk space'], answer: 1, explanation: 'Public CVEs essentially advertise attacks; patches close them — until applied, the door stays open.', unit: 4 },
  { id: 'ss-comp-80', q: 'Identity and Access Management (IAM) refers to:', choices: ['Encrypting hard drives', 'Ensuring users have the right level of access to the right resources at the right time', 'Tracking IP addresses only', 'Renaming files'], answer: 1, explanation: 'IAM enforces the principle of least privilege across an organisation.', unit: 4 },
  { id: 'ss-comp-81', q: 'A man-in-the-middle (MITM) attack involves:', choices: ['Two attackers cooperating', 'An attacker secretly intercepting and possibly altering communication between two parties', 'A virus replicating itself', 'A worm spreading through a network'], answer: 1, explanation: 'MITM defeats confidentiality and integrity in transit — mitigated by TLS and certificate validation.', unit: 4 },
  { id: 'ss-comp-82', q: 'An "insider threat" originates from:', choices: ['Foreign state actors', 'Current or former employees, contractors or partners with legitimate access', 'Random external scanners', 'Hardware manufacturers'], answer: 1, explanation: 'Insider threats are dangerous because the actor already has trusted access.', unit: 4 },
  { id: 'ss-comp-83', q: 'A risk of using third-party software is:', choices: ['It is always slower', 'Vulnerabilities or supply-chain compromises in the dependency become your organisation\'s problem', 'It cannot be tested', 'It does not need licences'], answer: 1, explanation: 'SolarWinds, Log4Shell and similar incidents illustrate supply-chain risk.', unit: 4 },
  { id: 'ss-comp-84', q: 'A risk of combining development, testing and production environments is:', choices: ['Better collaboration', 'Test data or partially developed code can leak into production, expanding the attack surface', 'Lower compute cost', 'Easier UI design'], answer: 1, explanation: 'Separated environments isolate failures and limit blast radius.', unit: 4 },
  { id: 'ss-comp-85', q: 'Code review is best described as:', choices: ['Automated linting only', 'Human peer inspection of code to find defects and improve quality', 'Profiling for performance', 'Compiling the program'], answer: 1, explanation: 'Code review catches bugs early and spreads knowledge across the team.', unit: 4 },
  { id: 'ss-comp-86', q: 'Encryption of data at rest primarily protects against:', choices: ['Performance bottlenecks', 'Unauthorised reading of data on stolen or compromised storage', 'Code style violations', 'Compiler warnings'], answer: 1, explanation: 'Encryption ensures that even if storage media is lost, the contents are unreadable without the key.', unit: 4 },
  { id: 'ss-comp-87', q: 'Threat modelling typically follows the principles of:', choices: ['Define security requirements, identify and mitigate threats, then confirm mitigation', 'Build first, secure later', 'Outsource and hope', 'Encrypt everything regardless of risk'], answer: 0, explanation: 'Per study design: define → identify/mitigate → confirm.', unit: 4 },
  { id: 'ss-comp-88', q: 'Which Australian framework lists eight prioritised mitigation strategies including patching, MFA and application control?', choices: ['Essential Eight', 'OWASP Top 10', 'NIST 800-53', 'GDPR'], answer: 0, explanation: 'The Essential Eight is published by the Australian Cyber Security Centre (ACSC).', unit: 4 },
  { id: 'ss-comp-89', q: 'The Information Security Manual (ISM) is published by:', choices: ['The VCAA', 'The Australian Cyber Security Centre / ASD', 'The Privacy Commissioner', 'GitHub'], answer: 1, explanation: 'The ISM is the federal cyber-security baseline for Australian government and is referenced by the study design.', unit: 4 },
  { id: 'ss-comp-90', q: 'Onboarding training focused on secure development primarily aims to:', choices: ['Reduce salary costs', 'Embed secure coding practices in developers from day one', 'Replace code review', 'Eliminate the need for patches'], answer: 1, explanation: 'Culture is a primary mitigation — trained developers introduce fewer vulnerabilities.', unit: 4 },
  { id: 'ss-comp-91', q: 'A risk management plan documents:', choices: ['Marketing slogans', 'Identified risks, their likelihood, impact and mitigation strategies', 'Source code', 'Only past incidents'], answer: 1, explanation: 'RMPs are central to organisational governance and are a recommended improvement strategy.', unit: 4 },
  { id: 'ss-comp-92', q: 'An ethical issue arising from using AI during software development is:', choices: ['Faster compilation', 'Potential use of copyrighted training material or introduction of biased / vulnerable code', 'Reduced electricity cost', 'Smaller binaries'], answer: 1, explanation: 'Provenance of AI-generated code and its potential vulnerabilities are active ethical concerns.', unit: 4 },
  { id: 'ss-comp-93', q: 'The "principle of least privilege" means:', choices: ['Give every user admin rights for convenience', 'Grant each user the minimum access required to do their job', 'Privileges should rotate randomly', 'Privileges only apply to managers'], answer: 1, explanation: 'Least privilege limits the damage if an account is compromised.', unit: 4 },
  { id: 'ss-comp-94', q: 'Regular updates and patches contribute to security by:', choices: ['Adding more features only', 'Closing known vulnerabilities before attackers exploit them', 'Resetting all passwords', 'Encrypting backups'], answer: 1, explanation: 'Patch management is one of the Essential Eight strategies.', unit: 4 },
  { id: 'ss-comp-95', q: 'Multi-factor authentication (MFA) typically requires:', choices: ['Two passwords', 'Two or more independent factors — e.g. something you know plus something you have', 'A single biometric scan only', 'A username only'], answer: 1, explanation: 'Factors include knowledge (password), possession (token) and inherence (biometric).', unit: 4 },
  { id: 'ss-comp-96', q: 'An ethical responsibility of a developer who finds a security flaw is to:', choices: ['Sell the flaw', 'Disclose it responsibly so it can be fixed before public exploitation', 'Post it on social media immediately', 'Ignore it'], answer: 1, explanation: 'Responsible disclosure balances transparency with user protection.', unit: 4 },
  { id: 'ss-comp-97', q: 'A separated production environment helps because:', choices: ['It looks nicer', 'Bugs and partial features cannot accidentally affect real users or data', 'It uses less storage', 'It bypasses version control'], answer: 1, explanation: 'Production should only ever run code that has passed dev and testing checks.', unit: 4 },
  { id: 'ss-comp-98', q: 'A consequence of ineffective software development practices for an organisation can be:', choices: ['Better Glassdoor reviews', 'Legal liability, reputational damage and financial loss', 'Reduced electricity bills', 'A larger headcount'], answer: 1, explanation: 'Outages, breaches and lawsuits all flow from poor dev hygiene.', unit: 4 },
  { id: 'ss-comp-99', q: 'Robust IAM combined with separated environments and regular patching is an example of:', choices: ['Defence in depth', 'Premature optimisation', 'Scope creep', 'Pseudocode'], answer: 0, explanation: 'Defence in depth layers multiple controls so a single failure does not compromise the system.', unit: 4 },
  { id: 'ss-comp-100', q: 'After mitigations are implemented, threat modelling requires you to:', choices: ['Skip all future reviews', 'Confirm that the identified threats have been adequately mitigated', 'Delete the threat list', 'Outsource the project'], answer: 1, explanation: 'The final step closes the loop — verify that mitigations actually address the threats.', unit: 4 },
];

